// KC-CLUB-FREIGABE (2.23.86, Wunsch Hansi): neue Funktionen nur sichtbar, wenn freigegeben – der Admin sieht sie immer (zum Testen, mit 🔒)
const frei = (id) => !!ICH?.admin || INIT?.freigaben?.[id] === "alle";
const nurTest = (id) => !!ICH?.admin && INIT?.freigaben?.[id] !== "alle";
// ---------- KC-CLUB-KREISE (0.60.0): Namenskreis ganz farbig nach Zustand – eine Registry für alle Listen ----------
// Reihenfolge = Vorrang. „fehler“ nur für den Admin (Server liefert fehler nur ihm). Unbekannt wird nie als OK gezeigt.
const KREIS_ARTEN = [
  { art: "fehler", text: "Fehler: Nachrichten kommen nicht an", farbe: "#c0392b", nurAdmin: true, gilt: (m) => ICH?.admin && !!m.fehler, info: (m) => m.fehler },
  { art: "online", text: "gerade online", farbe: "#1e8449", gilt: (m) => !!m.online },
  { art: "unbekannt", text: "unbekannt (online-Anzeige verborgen)", farbe: "transparent", gilt: (m) => !!m.verborgen },
  { art: "weg", text: "abwesend (Urlaub, krank, …)", farbe: "#d68910", gilt: (m) => !!m.status && !["verfuegbar", "ruhe"].includes(statusArt(m.status)) },
  { art: "heute", text: "heute in der App", farbe: "#2471a3", gilt: (m) => !!m.heute },
  { art: "selten", text: "länger nicht oder noch nie in der App", farbe: "#95a5a6", gilt: () => true },
];
function kreisArt(m) {
  // 2.23.93 (Hinweis Hansi): man selbst ist immer „gerade online“ – auch mit Inkognito (das verbirgt einen nur vor den anderen)
  if (m && ICH && m.person_id === ICH.person_id && !(ICH.admin && m.fehler)) m = { ...m, online: true };
  // KC-CLUB-ONLINE-EINE-QUELLE (2.24.18, Hinweis Hansi): „gerade online“ immer aus dem laufenden Online-Takt (dieselbe Quelle wie LED
  // und Zahl) – die Mitgliederliste wird nur beim Öffnen geladen und wäre sonst älter. Stand älter als 3 Min. → Wert aus der Liste.
  else if (m?.person_id && !m.verborgen) { try { if (ONL.stand && Date.now() - ONL.stand < 3 * 60 * 1000) m = { ...m, online: ONL.ids.has(m.person_id) }; } catch {} }
  const k = m ? KREIS_ARTEN.find((x) => (!x.nurAdmin || ICH?.admin) && x.gilt(m)) : null; return k || { art: "unbekannt", text: "unbekannt" };
}
const avFigurVon = (m) => m?.avatar || (m?.person_id && MITGLIEDER?.find?.((x) => x.person_id === m.person_id)?.avatar) || (m?.person_id && m.person_id === ICH?.person_id ? INIT?.einstellungen?.avatar?.figur : null) || null;
// Kreis-HTML: m = Mitglied aus MITGLIEDER (oder Online-Liste), groesse in px, extra = zusätzliche Attribute
function kreis(m, name, groesse = 40, extra = "") {
  const k = kreisArt(m), titel = k.info ? `${k.text} – ${k.info(m)}` : k.text;
  // KC-CLUB-AVATAR (2.23.85): gewählte Koch-Figur im Kreis – die Zustandsfarbe bleibt als Ring drumherum sichtbar
  const fig = avFigurVon(m);
  if (AVF_RE.test(fig || "")) avfMerken(m?.person_id, fig); // KC-CLUB-AVATAR-FOTO (2.23.89): Foto bei Bedarf nachladen
  // KC-CLUB-AVATAR-ABZEICHEN (2.23.89): mit Figur/Foto zusätzlich ein Abzeichen unten rechts (bei „unbekannt“ keins – nie wie OK aussehen)
  const abz = avGueltig(fig) && k.art !== "unbekannt" ? `<i class="k-abz a-${k.art}" aria-hidden="true">${k.art === "online" ? "✓" : k.art === "fehler" ? "!" : ""}</i>` : "";
  return `<div class="avatar k-${k.art}${avGueltig(fig) ? " mit-figur" : ""}" style="width:${groesse}px;height:${groesse}px${groesse > 60 ? ";font-size:1.6rem;margin:0 auto" : ""}${extra.includes("onclick") ? ";cursor:pointer" : ""}" title="${esc(titel)}" aria-label="${esc((name || "") + ": " + titel)}" ${extra}>${avGueltig(fig) ? avatarSvg(fig, groesse - 8, initialen(name || m?.name || "")) + abz : esc(initialen(name))}</div>`;
}
const kreisLegende = () => `<div class="kreislegende">${KREIS_ARTEN.filter((k) => !k.nurAdmin || ICH?.admin).map((k) =>
  `<span><i class="avatar k-${k.art}" style="width:14px;height:14px;${k.art === "unbekannt" ? "border-width:1px" : ""}"></i>${esc(k.text)}</span>`).join("")}</div>`;

let MG_EINMAL = null;
// KC-CLUB-ADMIN-NAME (1.99.0, Wunsch Hansi): Ansprechpartner in Texten = Vorname des Admins vom Server (fällt auf „Hansi“ zurück,
// solange nichts geladen ist). Feste Stellen im HTML tragen <span class="admin-name">, die nach dem Laden gefüllt werden.
const adminName = () => INIT?.adminName || "Hansi";
const adminNamenSetzen = () => document.querySelectorAll(".admin-name").forEach((e) => { e.textContent = adminName(); });
// ---------- KC-CLUB-ENTWICKLER (2.23.32, Wunsch Hansi): „Über die App“ mit Passbild und Lebenslauf – wie „Entwickler“ in KC Futura Academy ----------
// Foto aus KC Futura Academy (shared/hans-joachim-koch.jpg, dort schon öffentlich) als WebP ohne Kameradaten. Text wie dort, letzter Absatz für die Club-App.
const ENTWICKLER = { person_id: "KC-P-002", name: "Hans-Joachim Koch", bild: "entwickler-hans-joachim-koch.webp" };
function entwicklerZeigen() {
  const ich = ICH?.person_id === ENTWICKLER.person_id;
  blattAuf("entwicklerBlatt", `<div class="ew-kopf"><img class="ew-foto" src="${ENTWICKLER.bild}" alt="${esc(ENTWICKLER.name)}" width="120" height="161"><div>
      <h3 style="margin:0">${esc(ENTWICKLER.name)}</h3><div class="hinweis">Entwickler und Designer der Köcheclub-App</div>
      <div class="hinweis" style="margin-top:4px">👨‍🍳 Köcheclub Werne · since 1991</div></div></div>
    <p>Hans-Joachim Koch wurde 1961 in Holzwickede geboren. Bereits mit 16 Jahren begann er seine Ausbildung zum Koch. Nach mehreren Jahren Berufserfahrung legte er im Alter von 25 Jahren erfolgreich seine Meisterprüfung ab. Anschließend absolvierte er die Weiterbildung zum diätetisch geschulten Koch.</p>
    <p>Seine beruflichen Stationen führten ihn durch verschiedene Restaurants sowie Großküchen in Krankenhäusern, Altenheimen, Einrichtungen der Behindertenhilfe, Kindergärten und Schulen, in denen er bis zu seinem Ruhestand tätig war.</p>
    <p>Seit der Gründung des Köcheclubs Werne im Jahr 1991 ist er aktives Gründungsmitglied. Neben seiner Leidenschaft für das Kochen begeisterte ihn schon immer die Computertechnik.</p>
    <p>Die <b>Köcheclub-App</b> entwickelte er, damit alle Mitglieder einfach in Verbindung bleiben – Termine, Nachrichten, Dienstwünsche und vieles mehr an einem Ort, verständlich und kostenlos.</p>
    <p class="hinweis" style="margin:0 0 10px">Version ${esc(APP_VERSION)} · © 2026 Köcheclub Werne · kostenlos und werbefrei</p>
    <div class="knoepfe" style="flex-direction:column;align-items:stretch">${ich ? "" : `<button class="knopf haupt" onclick="fensterZu($('entwicklerBlatt'));direkt('${ENTWICKLER.person_id}')">💬 Hansi schreiben</button>`}
      <button class="knopf" onclick="fensterZu($('entwicklerBlatt'))">Schließen</button></div>`);
}
// KC-CLUB-ZURUECK-FENSTER (1.98.0): zuletzt gesetzter Verlaufseintrag (für „Zurück schließt nur das Fenster“)
const VERLAUF = { state: null, url: "" };
for (const m of ["pushState", "replaceState"]) { const o = history[m].bind(history); history[m] = (st, t, u) => { o(st, t, u); VERLAUF.state = history.state; VERLAUF.url = location.href; }; } // KC-CLUB-ONLINE-SEITE (1.91.0): einmaliger Filter der Mitglieder-Seite (früh deklariert, zeige() nutzt ihn)
