// Gewählt: Design + Modus (auto = nach Helligkeit: Lichtsensor, falls das Handy ihn freigibt, sonst Sonnenauf-/-untergang in Werne)
let DS = { design: "klassik", modus: "auto" }, dsGeaendert = 0, LICHT_NACHT = null;
try {
  const x = JSON.parse(localStorage.getItem("kc_club_design") || "null");
  if (x) DS = { design: x.design || "klassik", modus: x.modus || "auto" };
  else { const alt = localStorage.getItem("kc_club_dunkel"); DS.modus = alt === "1" ? "nacht" : alt === "0" ? "tag" : "auto"; } // bisheriger Schalter „Dunkles Design“
} catch {}
// Sonnenauf- und -untergang für Werne (51,66° N · 7,63° O), NOAA-Näherung, auf wenige Minuten genau
function sonne(d = new Date()) {
  const rad = Math.PI / 180, lat = 51.66 * rad, lon = 7.63;
  const n = Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 0)) / 864e5);
  const g = 2 * Math.PI / 365 * (n - 1);
  const zgl = 229.18 * (0.000075 + 0.001868 * Math.cos(g) - 0.032077 * Math.sin(g) - 0.014615 * Math.cos(2 * g) - 0.040849 * Math.sin(2 * g));
  const dekl = 0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g) - 0.006758 * Math.cos(2 * g) + 0.000907 * Math.sin(2 * g) - 0.002697 * Math.cos(3 * g) + 0.00148 * Math.sin(3 * g);
  const ha = Math.acos(Math.cos(90.833 * rad) / (Math.cos(lat) * Math.cos(dekl)) - Math.tan(lat) * Math.tan(dekl)) / rad;
  const mitte = 720 - 4 * lon - zgl, t0 = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  return { auf: new Date(t0 + (mitte - 4 * ha) * 6e4), unter: new Date(t0 + (mitte + 4 * ha) * 6e4) };
}
function istNacht() {
  if (DS.modus === "nacht") return true;
  if (DS.modus === "tag") return false;
  if (LICHT_NACHT !== null) return LICHT_NACHT;
  const j = new Date(), s = sonne(j); return j < s.auf || j > s.unter;
}
// Lichtsensor: nur wenn der Browser ihn anbietet (bei Chrome meist gesperrt) – dann mit Abstand zwischen Ein/Aus, damit nichts flackert
let lichtSensor = null;
function lichtSensorStarten() {
  if (lichtSensor || DS.modus !== "auto" || !("AmbientLightSensor" in window)) return;
  try {
    lichtSensor = new AmbientLightSensor({ frequency: 0.2 });
    lichtSensor.addEventListener("reading", () => {
      const lx = lichtSensor.illuminance, vorher = LICHT_NACHT;
      LICHT_NACHT = vorher === null ? lx < 15 : vorher ? !(lx > 50) : lx < 10;
      if (vorher !== LICHT_NACHT) anwendenDesign();
    });
    lichtSensor.addEventListener("error", () => { LICHT_NACHT = null; lichtSensor = null; });
    lichtSensor.start();
  } catch { lichtSensor = null; }
}
