  f.querySelectorAll("[data-antw]").forEach((b) => b.onclick = () => { const z = liste[Number(b.dataset.antw)]; zu();
    api("pinnwand_gesehen", { ids: liste.map((x) => x.id) }).catch(() => {}); pwAntworten(z.id, z.vonId, z.von); });
