  const h = alt[0] || "";
  if (!sbMerkbar(h)) { SBT.weiterHoeren = false; $("sbtErg").innerHTML = `<div class="sbt-nein">❌ ${h ? "Das war zu lang" : "Nichts verstanden"} – tippe nochmal auf 🎙️</div>`; return; }
