    + themen.map((t) => `<button class="${HZ.thema === t.id && !HZ.q ? "an" : ""}" onclick="hzThema('${t.id}')">${t.nr} ${t.sym} ${esc(t.t)}${anz(t.es.length)}</button>`).join("");
