    if ((m = /^💬 (.+)$/.exec(t))) return { art: "nachricht", text: `${w}${m[1]} hat dir eine Nachricht geschickt.` };
    if ((m = /^\S+ (.+): (.+)$/.exec(t))) return { art: "nachricht", text: `${w}${m[2]} hat in der Gruppe ${m[1]} geschrieben.` };
