// ---------- KC-CLUB-ANKLOPFEN-ERLAUBEN + Anklopfton (1.8.0, Wunsch Hansi) ----------
// Töne werden im Gerät erzeugt (Web Audio) – keine Tondateien, nichts zu laden. Neue Töne = neuer Eintrag hier.
const KLOPF_TOENE = [
  { id: "klopf", t: "🚪 Anklopfen (Holz)", n: [[150, 0, .09, "triangle", .7], [95, 0, .12, "sine", .5], [150, .2, .09, "triangle", .7], [95, .2, .12, "sine", .5], [150, .4, .09, "triangle", .7], [95, .4, .12, "sine", .5]] },
  { id: "dingdong", t: "🔔 Ding-Dong", n: [[784, 0, .7, "sine", .35], [622, .5, 1.1, "sine", .35]] },
  { id: "gong", t: "🥁 Gong", n: [[196, 0, 2.2, "sine", .45], [392, 0, 1.6, "sine", .12], [587, 0, 1.0, "sine", .06]] },
  { id: "glocke", t: "🛎️ Glöckchen", n: [[1568, 0, .8, "sine", .25], [2093, 0, .5, "sine", .08], [1568, .3, .8, "sine", .25], [2093, .3, .5, "sine", .08]] },
  { id: "aus", t: "🔕 Kein Ton (nur Vibration)", n: [] },
];
const klopfStand = () => ({ erlaubt: true, ton: "klopf", ...(INIT?.einstellungen?.anklopfen || {}) });
function klopfTonSpielen(id) {
  try { navigator.vibrate?.([120, 80, 120]); } catch {}
  const t = KLOPF_TOENE.find((x) => x.id === id) || KLOPF_TOENE[0];
  if (!t.n.length) return;
  try {
    audio = audio || new (window.AudioContext || window.webkitAudioContext)(); audio.resume?.();
    const jetzt = audio.currentTime + .02;
    for (const [f, ab, dauer, art, laut] of t.n) {
      const o = audio.createOscillator(), g = audio.createGain(); o.type = art; o.frequency.value = f;
      g.gain.setValueAtTime(.0001, jetzt + ab); g.gain.exponentialRampToValueAtTime(laut, jetzt + ab + .01); g.gain.exponentialRampToValueAtTime(.0001, jetzt + ab + dauer);
      o.connect(g).connect(audio.destination); o.start(jetzt + ab); o.stop(jetzt + ab + dauer + .05);
    }
  } catch {}
}
// KC-CLUB-ZULETZT-DA (1.20.0): „zuletzt da“ – Text aus der groben Server-Angabe { online, tag, zeit (nur heute), lange }
function zuletztText(z) {
  if (!z) return "";
  if (z.online) return "🟢 online";
  if (z.lange) return "länger nicht da";
  if (z.zeit) {
    const [h, m] = z.zeit.split(":").map(Number), [jh, jm] = new Intl.DateTimeFormat("de-DE", { timeZone: TZ, hour: "2-digit", minute: "2-digit" }).format(new Date()).split(":").map(Number);
    const min = jh * 60 + jm - (h * 60 + m);
    return min < 60 ? `zuletzt da vor ${Math.max(1, min)} Min.` : `zuletzt da heute ${z.zeit}`;
  }
  const tage = Math.round((Date.parse(heuteIso() + "T12:00:00Z") - Date.parse(z.tag + "T12:00:00Z")) / 86400000);
  return tage <= 1 ? "zuletzt da gestern" : tage < 7 ? `zuletzt da vor ${tage} Tagen` : `zuletzt da am ${z.tag.slice(8, 10)}.${z.tag.slice(5, 7)}.`;
}
