// KC-CLUB-GRUPPE-FARBEN (1.21.1): feste Farbe je Absender (aus dem Namen errechnet, bleibt immer gleich) – hell / dunkel
// Jeder in der Gruppe bekommt eine andere Farbe (Reihenfolge nach Name, bleibt im Chat gleich). Rot zuletzt – eigene Blasen sind rot.
const GRUPPEN_FARBEN = [["#1f618d", "#82b8ff"], ["#1e8449", "#7bd88f"], ["#7d3c98", "#d7a6f5"], ["#b9770e", "#ffc46b"], ["#117a65", "#5fd3bd"], ["#ad1457", "#ff8ac0"], ["#a04000", "#ffab73"], ["#2e4053", "#b8c7dc"], ["#6d4c41", "#d7b49e"], ["#c0392b", "#ff8a80"]];
function gruppenFarbe(name) {
  const namen = [...new Set((CHAT?.teilnehmer || []).filter((t) => t.person_id !== ICH?.person_id).map((t) => t.name))].sort((a, b) => a.localeCompare(b, "de"));
  let i = namen.indexOf(name);
  if (i < 0) { i = 0; for (const c of String(name || "")) i = (i * 31 + c.codePointAt(0)) >>> 0; } // ausgetreten → feste Farbe aus dem Namen
  const [hell, dunkel] = GRUPPEN_FARBEN[i % GRUPPEN_FARBEN.length]; return `--pf:${hell};--pfd:${dunkel}`;
}
