  try { navigator.permissions?.query({ name: "microphone" }).then((st) => { st.onchange = () => { if (st.state === "granted" && $("mikroHilfe")) mikroWeiterDiktieren(); }; }).catch(() => {}); } catch {}
  mikroMelden();
