const MIKRO_TASTATUR = `<p class="hinweis" style="margin:8px 0 4px">💡 Geht immer: <b>Mit dem Tastatur-Mikrofon sprechen</b> – ins Feld tippen und auf der Handy-Tastatur das 🎤 antippen.</p><button class="knopf" data-m="tastatur">🎤 Tastatur-Mikrofon nutzen</button>`;
const mikroCodeHtml = () => `<p class="hinweis" style="font-size:.75rem;margin:8px 0 0">Code: ${esc([MIKRO_DIAG.sprache, MIKRO_DIAG.gum, MIKRO_DIAG.stand].filter(Boolean).join(" · ") || "–")}</p>`;
function mikroKnoepfe(f) {
  f.querySelectorAll("[data-m]").forEach((b) => (b.onclick = () => (b.dataset.m === "tippen" ? mikroWeiterTippen() : b.dataset.m === "tastatur" ? mikroWeiterTippen(true) : mikroJetztFrei(b))));
}
function mikroMelden() { api("diagnose", { art: "mikro", daten: { sprache: MIKRO_DIAG.sprache || "", gum: MIKRO_DIAG.gum || "", stand: MIKRO_DIAG.stand || "", android: IST_ANDROID } }).catch(() => {}); }
async function mikroJetztFrei(knopf) {
  knopf.disabled = true;
  let ok = false, name = "";
  for (let v = 0; v < 2 && !ok; v++) { // belegt (z. B. Spracherkennung gibt das Mikrofon gerade frei) → kurz warten, nochmal
    try { const s = await navigator.mediaDevices.getUserMedia({ audio: true }); s.getTracks().forEach((x) => x.stop()); ok = true; }
    catch (e) { name = e?.name || "Fehler"; if (!/NotReadable|Abort|TrackStart/.test(name)) break; await new Promise((r) => setTimeout(r, 900)); }
  }
  knopf.disabled = false; MIKRO_DIAG.gum = ok ? "ok" : name; MIKRO_DIAG.stand = await mikroStand();
  if (ok) return mikroWeiterDiktieren();
  if (/NotAllowed|Security/.test(name)) { $("mikroAnl")?.classList.remove("versteckt"); if (knopf.dataset.m === "frei") knopf.classList.add("versteckt");
    melde("🎙️ Das Handy hat nicht gefragt – bitte einmal selbst erlauben (Anleitung im Fenster).", true); }
  else melde("🎙️ Das Mikrofon ist gerade belegt – z. B. von einem Anruf oder einer anderen App. Bitte gleich nochmal.", true);
  mikroMelden();
}
function mikroWeiterDiktieren() {
  lsSetzen(MIKRO_OK, "1"); $("mikroHilfe")?.remove();
  const w = MIKRO_WEITER; MIKRO_WEITER = null;
  // klappte das Mikrofon schon und die Spracherkennung meldet sich gleich wieder → beim nächsten Fehler die Google-Anleitung
  if (w) w.zweiter = true;
  melde("🎙️ Mikrofon ist frei – sprich einfach los.");
  if (w && $(w.ziel)) { DT.zweiter = true; diktatStart(w.ziel, w.nachSenden, { einmal: w.einmal }); }
}
function mikroWeiterTippen(tastatur) {
  const w = MIKRO_WEITER; MIKRO_WEITER = null; $("mikroHilfe")?.remove();
  const feld = w && $(w.ziel); if (feld) { feld.focus(); try { feld.setSelectionRange(feld.value.length, feld.value.length); } catch {} }
  if (tastatur) melde("⌨️ Jetzt auf der Handy-Tastatur das 🎤 antippen und sprechen.");
}
async function diktatStart(ziel, nachSenden, opt = {}) { // 2.22.0: auch für andere Felder (z. B. Notfall-Meldung) – ziel = Feld-ID, nachSenden = was „Senden“ tut
  if (!DIKTAT_GEHT) return ziel ? melde("Dieses Handy kann nicht diktieren – bitte tippen.", true) : spracheStart();
  if (DT.aktiv || DT.fragt) return;
  DT.fragt = true; let frei = false; try { frei = await mikroFreigabe(); } finally { DT.fragt = false; } // KC-CLUB-MIKRO-FREIGABE
  if (!frei || DT.aktiv) return;
  DT.ziel = ziel || "text"; DT.nachSenden = nachSenden || null; DT.einmal = !!opt.einmal; DT.weiterText = opt.weiter || ""; DT.immerWeiter = !!opt.immerWeiter; // 2.137.0: Brief-Assistent // 2.23.47: einmal = Suchfeld, nach dem ersten Satz fertig
  const feld = $(DT.ziel); DT.basis = feld.value; DT.fertig = ""; DT.aktiv = true; DT.seit = Date.now(); DT.vorher = []; DT.sitzung = []; DT.zwischen = "";
  const f = blattAuf("diktatBlatt", `<div class="diktat"><span class="bu-hpunkt">✍️</span><b>Ich schreibe mit …</b>
    <div class="diktat-text" id="diktatText"><span class="hinweis">Sprich einfach los. Satzzeichen sagen: „Punkt“, „Komma“, „Fragezeichen“, „neue Zeile“.</span></div>
    <div class="knoepfe" style="justify-content:center">${!ziel || nachSenden ? `<button class="knopf haupt" data-d="senden">${esc(opt.weiter || "📤 Senden")}</button>` : ""}<button class="knopf${!ziel || nachSenden ? "" : " haupt"}" data-d="fertig">✅ Fertig${!ziel || nachSenden ? " – noch prüfen" : ""}</button><button class="knopf" data-d="weg">✕ Verwerfen</button></div>
    <p class="hinweis" style="font-size:.8rem;margin:6px 0 0">🔒 Das Handy hört nur zu, solange dieses Fenster offen ist.</p></div>`);
  f.onclick = null; // nicht aus Versehen durch Tippen daneben schließen
  f.querySelectorAll("[data-d]").forEach((b) => (b.onclick = () => diktatEnde(b.dataset.d)));
  if (DT.ziel === "text" && chatId) tippenMelden(); // 2.529.0 KC-CLUB-SCHREIBT-HINWEIS: gleich „diktiert …“ melden, nicht erst beim ersten Wort
  diktatHoeren();
}
function diktatHoeren() {
  const Erk = window.SpeechRecognition || window.webkitSpeechRecognition, e = new Erk(); DT.erk = e;
  e.lang = "de-DE"; e.continuous = !DIKTAT_ANDROID; e.interimResults = true;
  e.onresult = (ev) => { DT.zweiter = false;
    // jedes Mal alle Ergebnisse dieser Hör-Runde neu zusammensetzen (nicht anhängen) – so entstehen keine Wiederholungen
    let fin = [], neu = "";
    for (let i = 0; i < ev.results.length; i++) { const r = ev.results[i], t = (r[0]?.transcript || "").trim(); if (!t) continue; if (r.isFinal) fin = diktatMerge(fin, t, true); else neu = t; }
    DT.sitzung = fin; DT.zwischen = neu;
    let teile = [...DT.vorher]; fin.forEach((t, i) => { teile = diktatMerge(teile, t, i > 0); }); if (neu) teile = diktatMerge(teile, neu, fin.length > 0);
    const gesagt = diktatSatz(teile.join(" ")), feld = $(DT.ziel || "text");
    feld.value = (DT.basis ? DT.basis.replace(/\s*$/, " ") : "") + gesagt; feld.dispatchEvent(new Event("input", { bubbles: true }));
    if ($("diktatText")) $("diktatText").textContent = gesagt || "…";
  };
  e.onerror = (ev) => { if (ev.error === "not-allowed" || ev.error === "service-not-allowed") { const weiter = { ziel: DT.ziel, nachSenden: DT.nachSenden, einmal: DT.einmal }, zweiter = DT.zweiter; DT.zweiter = false;
    lsSetzen(MIKRO_OK, ""); diktatEnde("fertig");
    // KC-CLUB-MIKRO-URSACHE: Mikrofon war gerade frei und trotzdem „not-allowed“ → Spracherkennung (Google) ist gesperrt
    if (zweiter && IST_ANDROID) { MIKRO_WEITER = weiter; MIKRO_DIAG = { sprache: ev.error, gum: "ok", stand: "nach-freigabe" }; return mikroHilfeGoogle(); }
    mikroHilfe(weiter, { sprache: ev.error }); } else if (ev.error === "audio-capture") { diktatEnde("fertig"); melde("🎙️ Das Mikrofon ist gerade belegt – z. B. von einem Anruf oder einer anderen App. Bitte gleich nochmal.", true); } }; // 2.22.12: Anleitung statt kurzer Meldung
  // Chrome hört nach einer Pause von selbst auf – solange das Fenster offen ist, weiter zuhören (höchstens 5 Minuten)
  e.onend = () => { for (const t of [...DT.sitzung, DT.zwischen]) DT.vorher = diktatMerge(DT.vorher, t); DT.sitzung = []; DT.zwischen = ""; // Runde abschließen
    if (DT.aktiv && DT.einmal && DT.vorher.length) return diktatEnde("fertig"); // 2.23.47: Suche – nach der ersten Pause fertig
    if (DT.aktiv && Date.now() - DT.seit < 5 * 60000) { try { diktatHoeren(); } catch { diktatEnde("fertig"); } } else if (DT.aktiv) diktatEnde("fertig"); };
  try { e.start(); } catch { melde("✍️ Mikrofon gerade nicht verfügbar.", true); diktatEnde("fertig"); }
}
function diktatEnde(was) {
  DT.aktiv = false; try { DT.erk?.stop?.(); } catch {}
  $("diktatBlatt")?.remove();
  const feld = $(DT.ziel || "text"); if (!feld) return;
  if (was === "weg") { feld.value = DT.basis; feld.dispatchEvent(new Event("input", { bubbles: true })); return melde("✕ Diktat verworfen"); }
  feld.value = feld.value.trim(); feld.dispatchEvent(new Event("input", { bubbles: true }));
  if (was === "senden" && DT.nachSenden) { if (!feld.value) return melde("Es wurde nichts erkannt – bitte nochmal.", true); return DT.nachSenden(); } // 2.22.0: z. B. Notfall-Meldung
  if (DT.immerWeiter && DT.nachSenden) return DT.nachSenden(); // 2.137.0: Brief-Assistent – auch „Fertig“ geht zum nächsten Schritt
  if (was === "senden") { if (!feld.value) return melde("Es wurde nichts erkannt – bitte nochmal.", true); return senden(); }
  feld.focus();
}
