// ---------- KC-CLUB-EINRICHTEN (1.87.0, Wunsch Hansi „Installation einfacher, nicht abschrecken“) ----------
// Erkennt Gerät + Browser und zeigt NUR die passenden Schritte – mit Bild des Browsers und Pfeil auf die richtige Stelle,
// beide üblichen Namen der Menüpunkte. iPhone/iPad: am Ende der Kurzcode für die neue Home-Bildschirm-App.
function einrichtenGeraet() {
  const ua = navigator.userAgent || "", ipad = /iPad/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  // KC-CLUB-EINRICHTEN-MINIBROWSER (1.98.0, Gesamtprüfung): aus WhatsApp, Facebook, Instagram oder Google Lens geöffnet → dort geht
  // „Installieren“ nicht; der Assistent zeigt dann zuerst „Im richtigen Browser öffnen“
  const inapp = /; wv\)|FBAN|FBAV|Instagram|Line\/|GSA\//.test(ua);
  if (/iPhone|iPod/.test(ua) || ipad) return { ios: true, ipad, inapp, name: ipad ? "iPad" : "iPhone", browser: /CriOS/.test(ua) ? "chrome" : /FxiOS/.test(ua) ? "firefox" : /EdgiOS/.test(ua) ? "edge" : "safari" };
  if (/Android/.test(ua)) return { android: true, inapp, name: "Android-Handy", browser: /SamsungBrowser/.test(ua) ? "samsung" : /Firefox/.test(ua) ? "firefox" : /EdgA\//.test(ua) ? "edge" : "chrome" }; // 2.276.0: Edge (Android) erkennen
  return { pc: true, name: "PC", browser: /Edg\//.test(ua) ? "edge" : /Firefox/.test(ua) ? "firefox" : "chrome" };
}
// kleines Bild des Browsers: Leiste oben oder unten, das gesuchte Zeichen leuchtet
const einrichtenBild = (lage, zeichen, ziel) => `<div class="er-geraet ${lage}"><div class="er-leiste">${zeichen.map((z, i) => `<span class="${i === ziel ? "er-ziel" : ""}">${z}</span>`).join("")}</div><div class="er-seite">🍳 Köcheclub</div></div>`;
