// KC-CLUB-ZUGANG-SELBST: neuen persönlichen Link per Mail anfordern (ohne Anmeldung; der Link geht nur an die hinterlegte Adresse)
// KC-CLUB-LINK-EINFUEGEN: persönlichen Link (oder nur den Schlüssel) einfügen → merken und App starten
function linkUebernehmen(text) {
  const t = String(text ?? $("linkEinfuegen").value).trim();
  const k = (/[?&]k=([0-9a-f]{32,96})/i.exec(t) || /^([0-9a-f]{32,96})$/i.exec(t) || [])[1];
  if (!k) return melde("Das sieht nicht wie ein persönlicher Link aus. Bitte den ganzen Link aus der Mail/WhatsApp kopieren.", true);
  try { localStorage.setItem("kc_club_key", k.toLowerCase()); } catch {}
  location.href = location.pathname + "?k=" + k.toLowerCase();
}
