let vbBlinkTimer = null;
function vbBlinken() { const l = $("ledDaten"); if (!l) return; l.classList.add("an"); clearTimeout(vbBlinkTimer); vbBlinkTimer = setTimeout(vbDatenLed, 140); }
function vbDatenLed() { const l = $("ledDaten"); if (l) l.classList.toggle("an", VB.laufend > 0); if (l) l.classList.toggle("flackern", VB.laufend > 0); }
