// Rundinstrument (Halbkreis): wert = null → „–“ (nicht gemessen), Zeiger ausgeblendet
function rundinstrument(titel, wert, max, einheit, zonen, dezimal = 0) {
  const w = 150, h = 92, cx = 75, cy = 80, r = 60;
  const pkt = (a) => [cx + r * Math.cos(Math.PI * (1 - a)), cy - r * Math.sin(Math.PI * (1 - a))];
  const bogen = (a, b, farbe) => { const [x1, y1] = pkt(a), [x2, y2] = pkt(b); return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} A${r} ${r} 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}" stroke="${farbe}" stroke-width="10" fill="none"/>`; };
  let vorher = 0; const b = zonen.map(([bis, farbe]) => { const s = bogen(vorher / max, Math.min(bis, max) / max, farbe); vorher = Math.min(bis, max); return s; }).join("");
  const a = wert == null ? null : Math.max(0, Math.min(1, wert / max));
  const zeiger = a == null ? "" : (() => { const [x, y] = [cx + (r - 14) * Math.cos(Math.PI * (1 - a)), cy - (r - 14) * Math.sin(Math.PI * (1 - a))]; return `<line x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}" stroke="var(--text)" stroke-width="3" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="5" fill="var(--text)"/>`; })();
  const zahl = wert == null ? "–" : wert.toLocaleString("de-DE", { maximumFractionDigits: dezimal });
  return `<div class="instrument"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(titel)}: ${zahl} ${einheit}">${b}${zeiger}</svg>
    <div class="i-wert">${zahl}<small> ${einheit}</small></div><div class="i-titel">${esc(titel)}</div></div>`;
}
const mittel = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
// ---------- KC-CLUB-NETZ-SYMBOL (2.429.0, Wunsch Hansi) ----------
