function fiPause() { const L = FI.lauf; if (!L) return; L.pause = !L.pause; try { speechSynthesis.cancel(); } catch {} fiLaufZeigen(); }
function fiWeiter() { const L = FI.lauf; if (!L) return; L.pause = false; L.rest = 1; fiTick(); }
