  const liste = fiAlle().filter((e) => { const t = berlinTagApp(e.z); return t >= Z.von && t < Z.bis && (!A.stufe || e.stufe === A.stufe) && (!A.gruppe || fiSek(e, A.gruppe) > 0); })
    .sort((a, b) => String(b.z).localeCompare(String(a.z)));
