      catch (e) { if (e?.zeit) { owSchreiben(owLesen().filter((y) => y.id !== x.id)); melde("Eine vorgemerkte Nachricht: der Server hat nicht rechtzeitig geantwortet – bitte im Chat prüfen, ob sie angekommen ist.", true); break; }
        if (e?.leitung || !navigator.onLine) break; owSchreiben(owLesen().filter((y) => y.id !== x.id)); melde(`Eine vorgemerkte Nachricht ging nicht: ${e.message}`, true); }
