// ---------- KC-CLUB-BOERSE (1.43.0, Wunsch Hansi): 🛍️ Börse – Biete / Suche, bis 3 Fotos, 30 Tage, Treffer-Meldung ----------
let BO = { d: null, form: null, filter: "alle", rubrik: "", oeffnen: null };
const boPreis = (a, d) => a.preis_art === "verschenken" ? "🎁 zu verschenken" : a.preis_art === "tausch" ? "🔄 Tausch" : a.preis !== null && a.preis !== undefined ? `💶 ${spEuro(a.preis)}${a.preis_art === "vb" ? " VB" : ""}` : "🤝 VB";
const boDatum = (iso) => iso ? iso.split("-").reverse().slice(0, 2).join(".") + "." : "";
