// KC-CLUB-SI-MUETZE (1.19.0): Mütze mit fortgesetzter Phase (negative Verzögerung = „läuft schon so lange“) – kein Neustart beim Neuzeichnen
const siMuetze = (klasse = "", label = "") => { const t = performance.now() / 1000;
  return `<span class="si-muetze ${klasse}" style="--si1:-${(t % 5).toFixed(2)}s;--si2:-${(t % 14).toFixed(2)}s"${label ? ` role="img" aria-label="${label}"` : ' aria-hidden="true"'}><span><img src="kc-kochmuetze-weiss.webp" alt=""></span></span>`; };
// ---------- KC-CLUB-SICHERHEIT (1.14.0, Wunsch Hansi): Sicherheits-Check – zeigt Mitgliedern, dass alles läuft und geschützt ist ----------
// Jede Zeile ist eine echte Prüfung (App oder Server). Keine Namen von Datenbanken/Anbietern. Regel 11: Was sich nicht prüfen
// lässt, steht als „nicht geprüft“ da – nie als OK. „Alle Systeme laufen einwandfrei“ nur, wenn wirklich jede Zeile OK ist.
// Registry SICHERHEIT_PRUEFUNGEN: neue Prüfung = neuer Eintrag (wert(r) liefert true/false/null, info(r) den Zusatztext).
const siZeit = (min) => min == null ? "" : min < 60 ? `vor ${Math.max(1, Math.round(min))} Min.` : min < 48 * 60 ? `vor ${Math.round(min / 60)} Std.` : `vor ${Math.round(min / 1440)} Tagen`;
const SICHERHEIT_PRUEFUNGEN = [
  { id: "verbindung", sym: "🔐", t: "Verbindung verschlüsselt", wert: () => location.protocol === "https:", info: () => location.protocol === "https:" ? "Alles, was du sendest, ist auf dem Weg geschützt" : "Seite nicht über eine geschützte Verbindung geöffnet" },
  { id: "zugang", sym: "🔑", t: "Dein persönlicher Zugang ist gültig", wert: (r) => r.zugang, info: (r) => r.zugang ? "Nur mit deinem eigenen Link" : "" },
  { id: "server", sym: "🛰️", t: "Server erreichbar", wert: (r) => r.serverMs != null, info: (r) => r.serverMs != null ? `Antwort in ${r.serverMs} ms` : "" },
  { id: "datenbank", sym: "🗄️", t: "Daten-Speicher antwortet", wert: (r) => r.s ? r.s.dbMs != null : null, info: (r) => r.s?.dbMs != null ? `Antwort in ${r.s.dbMs} ms` : "" },
  { id: "verschluesselt", sym: "🔒", t: "Daten verschlüsselt gespeichert", fest: true, wert: (r) => r.s ? r.s.dbMs != null : null, info: () => "Fest eingebaut – lässt sich nicht abschalten" },
  { id: "schutz", sym: "🧱", t: "Zugriffsschutz auf allen Daten", wert: (r) => r.s?.schutz ?? null, info: () => "Jeder sieht nur, was er sehen darf" },
  { id: "spiegel", sym: "🪞", t: "Sicherungskopie in zweitem Speicher aktuell", wert: (r) => r.s?.spiegel ?? null, info: (r) => r.s?.spiegelMin != null ? `Abgeglichen ${siZeit(r.s.spiegelMin)}` : "" },
  { id: "sicherung", sym: "💾", t: "Nächtliche Datensicherung", wert: (r) => r.s?.sicherung ?? null, info: (r) => r.s?.sicherungAm ? `Zuletzt ${new Date(r.s.sicherungAm).toLocaleString("de-DE", { weekday: "short", hour: "2-digit", minute: "2-digit" })} Uhr` : "" },
  { id: "wiederherstellung", sym: "♻️", t: "Wiederherstellung erfolgreich getestet", wert: (r) => r.s?.wiederherstellung ?? null, info: () => "Die Sicherung wird regelmäßig zur Probe zurückgespielt" },
  { id: "ueberwachung", sym: "👁️", t: "Überwachung rund um die Uhr aktiv", wert: (r) => r.s?.ueberwachung ?? null, info: (r) => r.s?.ueberwachungMin != null ? `Letzte Kontrolle ${siZeit(r.s.ueberwachungMin)}` : "" },
  { id: "version", sym: "🔄", t: "App auf dem neuesten Stand", wert: (r) => r.neueste == null ? null : r.neueste === APP_VERSION, info: (r) => r.neueste && r.neueste !== APP_VERSION ? `Neu: v${r.neueste} – unter Technik → Update` : `v${APP_VERSION}` },
];
// Rundinstrumente: Grenzen je Messung (ms) – schnell / normal / langsam, immer mit Wort (nicht nur Farbe)
const SI_UHREN = [
  { id: "server", t: "App ↔ Server", max: 2500, gut: 1000, mittel: 2000, wert: (r) => r.serverMs }, // 2.23.73 (Wunsch Hansi): Handy-Netz realistisch – bis 1 s grün
  { id: "datenbank", t: "Daten-Speicher", max: 1000, gut: 300, mittel: 700, wert: (r) => r.s?.dbMs ?? null },
];
