      await api("nachricht_senden", { text: `↩️ Rückfrage zu deiner Startnachricht „${kurz}“:\n${frage}`, wege: ["push"], empfaenger: { personen: [x.von], aemter: [], alle: false, vorstand: false }, betreff: "" })
