        if (nochmal && x.versuche <= SQ_WARTEN_MS.length) { x.status = "wartet"; x.naechster = Date.now() + SQ_WARTEN_MS[x.versuche - 1]; }
        else { x.status = "fehler"; x.fehler = String(e?.message || "Fehler").slice(0, 200); }
