    $("scFestBlatt")?.remove(); SC.gewaehlt = []; SC.datum = datum; SC.von = von; SC.bis = bis;
    if (r.termin?.fehler) melde(`Gespeichert als geplanter Besuch (${r.besuch.besuch_id}) – aber Bestätigung: ${r.termin.fehler}`, true);
    else scVersand(r.termin, `📅 Termin bestätigt – ${wann}`);
    await bsLaden(); await scLaden();
