  const f = blattAuf("smVBlatt", `<h3 style="margin:0">💬 Kein Termin passt</h3><p class="hinweis" style="margin:0">Schlag Hansi bis zu zwei Termine vor.</p>${zeile(1)}${zeile(2)}
    <label class="feld">Bemerkung (freiwillig)<input id="smBem" maxlength="500" data-diktat placeholder="z. B. vormittags geht es bei mir nicht"></label>
    <button class="knopf haupt" id="smVOk">📨 Vorschlag schicken</button><button class="knopf" onclick="$('smVBlatt').remove()">Abbrechen</button>`);
  f.style.zIndex = "2100"; f.onclick = null; // 2.23.63: nicht aus Versehen schließen
  f.querySelectorAll("[data-ort]").forEach((g) => g.querySelectorAll(".chip").forEach((c) => (c.onclick = () => g.querySelectorAll(".chip").forEach((x) => x.classList.toggle("an", x === c)))));
  f.querySelector("#smVOk").onclick = async function () {
    const v = [1, 2].map((n) => ({ datum: $("smD" + n).value, von: $("smV" + n).value, bis: $("smB" + n).value, besuchsart: f.querySelector(`[data-ort="${n}"] .chip.an`)?.dataset.w || "egal" })).filter((x) => x.datum && x.von);
    if (!v.length) return melde("📅 Bitte mindestens einen Tag und eine Uhrzeit eintragen.", true);
    if (v.some((x) => x.bis && x.bis <= x.von)) return melde("„Bis“ muss nach „Von“ liegen.", true);
    f.remove(); smTun(null, { einladung_id: id, was: "gegenvorschlag", vorschlaege: v, bemerkung: $("smBem")?.value || "" }, "📨 Vorschlag ist bei Hansi");
  };
