  // Haken der folgenden eigenen Punkte nachrücken
  const h = {}; for (const [k, v] of Object.entries(st.haken)) { if (!k.startsWith("e")) h[k] = v; else { const n = +k.slice(1); if (n < i) h[k] = v; else if (n > i) h["e" + (n - 1)] = v; } }
