  const schrift = (pt, art = SANS, fett = false) => { g.font = `${fett ? "bold " : ""}${Math.round(pt * K * 0.3528)}px ${art}`; };
  g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height);
