      if (z.linie) { g.strokeStyle = "#888"; g.lineWidth = mm(0.3); g.beginPath(); g.moveTo(mm(x + 9), mm(zy + 0.6)); g.lineTo(mm(x + w - 3), mm(zy + 0.6)); g.stroke(); }
