// KC-CLUB-PROTOKOLL-NEU-INFO: „Besprechung“ → „Neues Besprechungsprotokoll eingestellt“; längere Titel → „Neues Protokoll eingestellt: …“
function protokollNeuText(pn) { // Funktionsdeklaration: schon beim ersten Zeichnen des Info-Feldes verfügbar
  if (!pn?.titel) return "Neues Protokoll eingestellt";
  if (/protokoll$/i.test(pn.titel)) return `Neues ${pn.titel} eingestellt`;
  return /^[A-ZÄÖÜ][a-zäöüß]+$/.test(pn.titel) ? `Neues ${pn.titel}${/(ung|heit|keit|schaft)$/.test(pn.titel) ? "s" : ""}protokoll eingestellt` : `Neues Protokoll eingestellt: ${pn.titel}`;
}
const dz = (iso) => fKurzJahr.format(new Date(iso.slice(0, 10) + "T12:00:00Z"));
const dWt = new Intl.DateTimeFormat("de-DE", { timeZone: "UTC", weekday: "short" });
const kwVon = (iso) => { const d = new Date(iso + "T12:00:00Z"), t = (d.getUTCDay() + 6) % 7; d.setUTCDate(d.getUTCDate() - t + 3); const j = new Date(Date.UTC(d.getUTCFullYear(), 0, 4)); return 1 + Math.round(((d - j) / 86400000 - 3 + ((j.getUTCDay() + 6) % 7)) / 7); };
// ---- Termine: Kalender (Tag/Woche/Monat/Jahr) oder To-do-Liste ----
function druckTermineOptionen() {
  const art = termineArt === "todo" ? "todo" : termineArt === "kalender" && kalTagWahl ? "tag" : "monat";
  return `<b>Was drucken?</b><div class="dwahl">${[["tag", "📄 Tag"], ["woche", "🗓️ Woche"], ["monat", "📅 Monat"], ["jahr", "📆 Jahr"], ["todo", "✅ To-do-Liste"]]
      .map(([v, t]) => `<label><input type="radio" name="dArt" value="${v}" ${v === art ? "checked" : ""} onchange="druckOptSicht()"> ${t}</label>`).join("")}</div>
    <div id="dKal"><label class="feld">Datum <small class="hinweis">(der Tag / die Woche / der Monat / das Jahr, in dem es liegt)</small><input type="date" id="dDatum" value="${kalTagWahl || heuteIso()}"></label>
      <b style="display:block;margin-top:10px">Was soll drauf?</b><div class="dhaken">${DRUCK_INHALTE.map(([k, t]) => `<label><input type="checkbox" data-inhalt="${k}" ${(k === "feiertag" && !einst("feiertage", true)) || (k === "ferien" && !einst("ferien", true)) ? "" : "checked"}> ${t}</label>`).join("")}</div></div>
    <div id="dTodo"><label class="feld">Welche Aufgaben?<select id="dTodoFilter"><option value="alle">Alle</option><option value="mir">👉 Mir zugewiesen</option><option value="ich">👤 Nur meine</option><option value="gemeinsam">👥 Für alle</option></select></label>
      <label class="feld">Geordnet nach<select id="dTodoGruppe"><option value="wer">Zuständigen</option><option value="kategorie">Kategorie</option><option value="faellig">Fälligkeit</option></select></label>
      <label class="schalter" style="margin-top:8px"><span>Erledigte mitdrucken</span><input type="checkbox" id="dTodoErl"></label></div>`;
}
async function kalenderDaten(von, bis) {
  const d = { treffen: [], aktionen: [], dienste: [], fristen: [], geburtstage: [] }, ids = new Set();
  for (let a = von; a <= bis; a = tagPlus(a, 60)) {
    const e = tagPlus(a, 59) < bis ? tagPlus(a, 59) : bis, r = await api("kalender", { von: a, bis: e }, { warten: true });
    for (const k of ["treffen", "aktionen", "fristen"]) for (const x of r[k] || []) if (!ids.has(k + x.id)) { ids.add(k + x.id); d[k].push(x); }
    for (const x of r.dienste || []) if (!ids.has("d" + x.datum + x.start)) { ids.add("d" + x.datum + x.start); d.dienste.push(x); }
    d.geburtstage = r.geburtstage || d.geburtstage;
  }
  return d;
}
function druckEintrag(x, lang) {
  if (x.art === "treffen" || x.art === "veranst") {
    const t = x.t, b = new Date(t.beginn), e = t.ende ? new Date(t.ende) : null, gleich = e && berlinIso(t.beginn) === berlinIso(t.ende);
    const zeit = t.ganztaegig ? "ganztägig" : fZeit.format(b) + (gleich ? "–" + fZeit.format(e) : "");
    const ort = t.ort || (t.gastgeber ? "bei " + t.gastgeber.name : "");
    return { zeit, text: `${x.art === "veranst" ? "🎪" : "🍽️"} ${t.titel}${t.status === "abgesagt" ? " (abgesagt)" : ""}`,
      info: [ort && "📍 " + ort, lang && t.beschreibung, lang && x.art === "treffen" && `✅ ${t.ja} · ❓ ${t.vielleicht} · ❌ ${t.nein}`,
        lang && x.art === "treffen" && t.ja && "Zusagen: " + t.teilnahme.filter((y) => y.antwort === "ja").map((y) => y.name).join(", ")].filter(Boolean).join(" · ") };
  }
  if (x.art === "aktion") return { zeit: "", text: `🧳 ${x.a.titel}`, info: [x.a.veranstalter, x.a.von !== x.a.bis && `${dz(x.a.von)} – ${dz(x.a.bis)}`].filter(Boolean).join(" · ") };
  if (x.art === "dienst") return { zeit: `${x.d.start}–${x.d.ende}`, text: "🗓️ Mein Dienst", info: x.d.bereich || "" };
  if (x.art === "frist") return { zeit: fZeit.format(new Date(x.f.frist)), text: `🗳️ Abstimmung endet: ${x.f.titel}`, info: "" };
  if (x.art === "geb") return { zeit: "", text: `🎂 ${x.g.name}`, info: "" };
  if (x.art === "ferien") return { zeit: "", text: `🏖️ ${x.name}`, info: "Ferien" };
  return { zeit: "", text: `🇩🇪 ${x.name}`, info: "Feiertag" };
}
async function druckKalender(o) {
  const tag = o.datum, j = +tag.slice(0, 4), m = +tag.slice(5, 7);
  let von, bis, titel, unter = "";
  if (o.art === "tag") { von = bis = tag; titel = "Tageskalender"; unter = fTagLang.format(new Date(tag + "T12:00:00Z")) + " " + j; }
  else if (o.art === "woche") { von = montag(tag); bis = tagPlus(von, 6); titel = `Wochenkalender – KW ${kwVon(von)}`; unter = `${dz(von)} bis ${dz(bis)}`; }
  else if (o.art === "monat") { von = `${j}-${String(m).padStart(2, "0")}-01`; bis = tagPlus(`${m === 12 ? j + 1 : j}-${String(m === 12 ? 1 : m + 1).padStart(2, "0")}-01`, -1); titel = `Monatskalender – ${MONATE[m - 1]} ${j}`; }
  else { von = `${j}-01-01`; bis = `${j}-12-31`; titel = `Jahresübersicht ${j}`; }
  if (!o.inhalte.length) throw new Error("Bitte mindestens einen Inhalt ankreuzen.");
  const daten = await kalenderDaten(von, bis);
  const eintr = (t) => kalEintraege(t, daten, o.inhalte.includes("feiertag")).filter((x) => o.inhalte.includes(x.art === "veranst" ? "treffen" : x.art));
  const tage = []; for (let t = von; t <= bis; t = tagPlus(t, 1)) tage.push(t);
  const legende = `<p class="dlegende">${DRUCK_INHALTE.filter(([k]) => o.inhalte.includes(k)).map(([, t]) => t).join(" · ")}</p>`;
  if (o.art === "tag") {
    const e = eintr(tag).map((x) => druckEintrag(x, true));
    return { titel, unter, html: e.length ? `<table><thead><tr><th style="width:22mm">Zeit</th><th>Termin</th></tr></thead><tbody>${e.map((x) => `<tr><td>${esc(x.zeit || "–")}</td><td><b>${esc(x.text)}</b>${x.info ? `<div class="dklein">${esc(x.info)}</div>` : ""}</td></tr>`).join("")}</tbody></table>`
      : '<p>An diesem Tag stehen keine Termine im Kalender.</p>' };
  }
  if (o.art === "woche") return { titel, unter, html: `<table><thead><tr><th style="width:30mm">Tag</th><th>Termine</th></tr></thead><tbody>${tage.map((t, i) => { const e = eintr(t).map((x) => druckEintrag(x, false));
      return `<tr class="${i >= 5 ? "we" : ""}"><td><b>${esc(dWt.format(new Date(t + "T12:00:00Z")))}</b> ${esc(dz(t).slice(0, 6))}</td><td style="height:22mm">${e.map((x) => `<div><b>${esc(x.zeit ? x.zeit + " " : "")}</b>${esc(x.text)}${x.info ? ` <span class="dklein">– ${esc(x.info)}</span>` : ""}</div>`).join("")}</td></tr>`; }).join("")}</tbody></table>${legende}` };
  if (o.art === "monat") {
    const start = montag(von), wochen = []; for (let t = start; t <= bis; t = tagPlus(t, 7)) wochen.push(t);
    return { titel, quer: true, html: `<table class="dmonat"><thead><tr>${["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"].map((w) => `<th>${w}</th>`).join("")}</tr></thead><tbody>${wochen.map((w) => `<tr>${[0, 1, 2, 3, 4, 5, 6].map((i) => {
      const t = tagPlus(w, i), drin = t >= von && t <= bis, e = drin ? eintr(t).map((x) => druckEintrag(x, false)) : [], ft = e.some((x) => x.info === "Feiertag");
      return `<td class="${!drin ? "aus" : ""} ${i >= 5 ? "we" : ""} ${ft ? "ft" : ""}"><div class="dtag">${+t.slice(8)}</div>${e.slice(0, 5).map((x) => `<div class="dklein">${esc((x.zeit ? x.zeit.split("–")[0] + " " : "") + x.text)}</div>`).join("")}${e.length > 5 ? `<div class="dklein">+ ${e.length - 5} weitere</div>` : ""}</td>`; }).join("")}</tr>`).join("")}</tbody></table>${legende}` };
  }
  const monate = MONATE.map((name, mi) => { const e = tage.filter((t) => +t.slice(5, 7) === mi + 1).flatMap((t) => eintr(t).filter((x) => x.art !== "dienst" || o.inhalte.includes("dienst")).map((x) => ({ t, ...druckEintrag(x, false) })));
    return `<div class="djahrmonat"><h2>${name}</h2>${e.length ? e.map((x) => `<div class="dklein"><b>${esc(dWt.format(new Date(x.t + "T12:00:00Z")))} ${esc(dz(x.t).slice(0, 6))}</b> ${esc(x.text)}</div>`).join("") : '<div class="dklein">–</div>'}</div>`; });
  return { titel, html: `<div class="djahr">${monate.join("")}</div>${legende}` };
}
async function druckTodo(o) {
  if (!TODO.eintraege.length) { const r = await api("todo_liste", {}, { warten: true }); TODO.eintraege = r.eintraege || []; TODO.kategorien = r.kategorien || TODO.kategorien; }
  const kat = (id) => TODO.kategorien.find((k) => k.id === id) || { sym: "📝", name: "Sonstiges" };
  const zust = (x) => (x.zustaendige?.length ? x.zustaendige : x.zustaendig ? [x.zustaendig] : []);
  let l = TODO.eintraege.filter((x) => (o.todoErledigte || !x.erledigt) && (o.todoFilter === "alle" || (o.todoFilter === "mir" ? zust(x).some((z) => z.ich) : o.todoFilter === "ich" ? x.fuer === "ich" : x.fuer === "alle")));
  if (!l.length) throw new Error("Keine Aufgaben für diese Auswahl.");
  const gruppen = new Map(), schl = (x) => (o.todoGruppe === "kategorie" ? `${kat(x.kategorie).sym} ${kat(x.kategorie).name}` : o.todoGruppe === "faellig" ? (x.faellig ? (x.faellig < heuteIso() ? "⚠️ überfällig" : "fällig bis " + dz(x.faellig)) : "ohne Termin") : zust(x).length ? "👉 " + zust(x).map((z) => z.vorname).join(", ") : "👉 noch offen – niemand zugewiesen");
  for (const x of [...l].sort((a, b) => (a.faellig || "9999").localeCompare(b.faellig || "9999"))) gruppen.set(schl(x), [...(gruppen.get(schl(x)) || []), x]);
  const namen = { alle: "alle Aufgaben", mir: "mir zugewiesen", ich: "nur meine", gemeinsam: "für alle" };
  return { titel: "To-do-Liste", unter: `${namen[o.todoFilter]} · ${l.length} Aufgabe${l.length === 1 ? "" : "n"}${o.todoErledigte ? " (mit erledigten)" : ""}`,
    html: [...gruppen].map(([g, xs]) => `<h2>${esc(g)}</h2><table><thead><tr><th style="width:9mm">✓</th><th>Aufgabe</th><th style="width:38mm">Zuständig</th><th style="width:22mm">bis</th><th style="width:28mm">Kategorie</th></tr></thead><tbody>
      ${xs.map((x) => `<tr><td>${x.erledigt ? "☑" : '<span class="kaestchen"></span>'}</td><td>${esc(x.text)}${x.fuer === "alle" ? ' <span class="dklein">(für alle)</span>' : ""}${x.erledigt ? `<div class="dklein">erledigt ${esc(x.erledigtVon || "")}</div>` : ""}</td>
        <td>${esc(zust(x).map((z) => z.vorname).join(", ") || "–")}</td><td>${x.faellig ? esc(dz(x.faellig)) : "–"}</td><td>${esc(kat(x.kategorie).sym + " " + kat(x.kategorie).name)}</td></tr>`).join("")}</tbody></table>`).join("") };
}
