function arDateiSym(mime) { return /pdf/.test(mime || "") ? "📕" : /^image\//.test(mime || "") ? "🖼️" : /word/.test(mime || "") ? "📝" : /excel|sheet/.test(mime || "") ? "📊" : "📄"; }
