  const hier = arVorschlag(text, [o]), alle = arVorschlag(text, d.ordner.filter((y) => !y.auto && y.art !== "chronik" && (y.besitzer || null) === (o.besitzer || null) && (!o.besitzer || y.eigen) && (y.eigen || d.darf)).sort((a, b) => b.jahr - a.jahr));
