// ----- 1.19.0: Protokoll (Text als Datei + auf Wunsch die Protokoll-Dateien/Fotos) -----
function protokollText(p) {
  const l = (t, a) => a?.length ? [`${t}:`, ...a.map((x, i) => `  ${i + 1}. ${typeof x === "string" ? x : x.name}`), ""] : [];
  return [`Köcheclub Werne – Protokoll`, p.titel, `${tagKurz(p.datum)}${p.ort ? " · " + p.ort : ""} · geschrieben von ${p.verfasser?.name || ""}${p.version > 1 ? ` · Fassung ${p.version}` : ""}`, "────────────────────", "",
    ...(p.anwesend?.length ? [`Anwesend (${p.anwesend.length}): ${p.anwesend.map((x) => x.name).join(", ")}`] : []), ...(p.entschuldigt?.length ? [`Entschuldigt: ${p.entschuldigt.map((x) => x.name).join(", ")}`] : []),
    ...(p.gaeste ? [`Gäste: ${p.gaeste}`] : []), "", ...l("Tagesordnung", p.tagesordnung), ...l("Beschlüsse", p.beschluesse), ...(p.kurzfassung ? ["Kurzfassung:", p.kurzfassung, ""] : []), ...(p.naechster_termin ? [`Nächster Termin: ${p.naechster_termin}`, ""] : []),
    ...l("Anlagen", PR.anlagen), `Abgelegt am ${zeitDe(new Date().toISOString())} von ${ICH.name}`, ""].join("\n");
}
function protokollInsArchiv() {
  const p = PR?.protokoll; if (!p) return;
  const dateien = (PR.anlagen || []).filter((a) => ARCHIV_TYP_OK(a.mime)), titel = `Protokoll ${p.titel} (${tagKurz(p.datum)})`.slice(0, 120);
  archivAblageFragen("protokoll", { titel, datum: String(p.datum || "").slice(0, 10) || heuteIso(),
    wahl: dateien.length ? { text: `📎 Protokoll-Dateien/Fotos mit ablegen (${dateien.length})` } : null,
    dateien: async (mitDateien) => {
      const aus = [{ titel, name: `Protokoll-${String(p.datum || "").slice(0, 10)}.txt`, mime: "text/plain", blob: textDatei(protokollText(p)), stichworte: "Text" }];
      if (mitDateien) for (const a of dateien) { const f = await anlageAlsDatei(a); aus.push({ titel: `${a.name} (Protokoll ${p.titel})`.slice(0, 120), name: f.name, mime: f.mime, blob: f.blob, stichworte: "Anlage" }); }
      return aus;
    } });
}
// Bild eines Blattes (gut lesbar, Hochformat) für die Ablage – nur Text, keine Emojis (Schrift fehlt auf manchen Geräten)
function ablageBild({ kopf, zeilen, fuss }) {
  const B = 1000, R = 48, c = document.createElement("canvas"), g = c.getContext("2d");
  const KLEIN = "28px sans-serif", GROSS = "bold 34px sans-serif";
  const umbrechen = (text) => {
    g.font = GROSS; const aus = [];
    for (const absatz of String(text).split("\n")) {
      let z = "";
      for (const w of absatz.split(" ")) { const t = z ? z + " " + w : w; if (g.measureText(t).width > B - 2 * R - 20 && z) { aus.push(z); z = w; } else z = t; }
      aus.push(z);
    }
    return aus;
  };
  const bloecke = zeilen.map(([t, w]) => ({ t, w: umbrechen(w) }));
  const H = 180 + bloecke.reduce((s, b) => s + 42 + b.w.length * 44 + 22, 0) + 90;
  c.width = B; c.height = H;
  g.fillStyle = "#ffffff"; g.fillRect(0, 0, B, H);
  g.strokeStyle = "#7a1e2c"; g.lineWidth = 8; g.strokeRect(12, 12, B - 24, H - 24);
  g.fillStyle = "#7a1e2c"; g.font = "bold 50px sans-serif"; g.fillText(kopf, R, 100);
  let y = 180;
  for (const b of bloecke) {
    g.fillStyle = "#666666"; g.font = KLEIN; g.fillText(b.t, R, y); y += 42;
    g.fillStyle = "#111111"; g.font = GROSS; for (const z of b.w) { g.fillText(z, R, y); y += 44; }
    g.strokeStyle = "#dddddd"; g.lineWidth = 2; g.beginPath(); g.moveTo(R, y - 18); g.lineTo(B - R, y - 18); g.stroke(); y += 22;
  }
  g.fillStyle = "#666666"; g.font = KLEIN; g.fillText(fuss, R, H - 50);
  return new Promise((ok, nein) => c.toBlob((b) => (b ? ok(b) : nein(new Error("Bild konnte nicht erstellt werden."))), "image/png"));
}
// ----- KC-CLUB-ARCHIV-PERSOENLICH (1.5.0): eigener Ordner, Freigaben auf Zeit, Prüfung von Einreichungen -----
